SELECT #{start} time,proto_type type,SUM(c2s_byte_len)+SUM(s2c_byte_len) count
FROM traffic_protocol_statistic

  WHERE stat_time >= #{start}
  AND stat_time < #{end}

GROUP BY proto_type;

select #{start} time,proto_type type,max(link_num) linknum ,sum(c2s_pkt_num)+sum(s2c_pkt_num) pakeagenum,
sum(c2s_byte_len)+sum(s2c_byte_len) bytes
FROM traffic_protocol_statistic

    WHERE stat_time >= #{start}
    AND stat_time < #{end}

GROUP BY proto_type

SELECT stat_time time ,ip_addr ip,area_id area,link_num links,c2s_pkt_num+s2c_pkt_num packets,
 c2s_byte_len+s2c_byte_len bytes
 FROM traffic_ip_active_statistic

   WHERE stat_time >= #{start}
   AND stat_time < #{end}


	SELECT #{start} time,t.node_ip area,sum(t.speed) bps
	        from ( SELECT RECV_TIME,NODE_IP,INOCTETS_SPEED+OUTOCTETS_SPEED as speed FROM traffic_netflow_port_info
           where RECV_TIME >= #{start}
           and RECV_TIME < #{end} ) t
    GROUP BY area;


        SELECT #{start} time,t.port port ,avg(t.speed)  bps
        from ( SELECT RECV_TIME,PORT,INOCTETS_SPEED+OUTOCTETS_SPEED as speed
               FROM traffic_netflow_port_info
              where RECV_TIME >= #{start}
			  and RECV_TIME < #{end} ) t
         GROUP BY port;

SELECT stat_time
FROM traffic_protocol_statistic

where stat_time < #{end}

ORDER BY stat_time desc
LIMIT 1;

